D83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23\uD83E\uDD23"
            )
        }
    }

    val listState = rememberLazyListState()

    Scaffold(
        topBar = {
            Box(
                modifier = Modifier.Companion
                    .fillMaxWidth()
                    .windowInsetsPadding(
                        WindowInsets.Companion.safeDrawing.only(
                            WindowInsetsSides.Companion.Top + WindowInsetsSides.Companion.Horizontal
                        )
                    )
                    .padding(12.dp)
            ) {
                Text("Scroll Mode - viewport")
            }
        },
        bottomBar = {
            Box(
                Modifier.Companion
                    .fillMaxWidth()
                    .windowInsetsPadding(
                        WindowInsets.Companion.safeDrawing.only(
                            WindowInsetsSides.Companion.Bottom + WindowInsetsSides.Companion.Horizontal
                        )
                    )
                //.fillMaxWidth().height(56.dp)
            ) {
                InputBar { text ->
                    messages.add(text)
                }
            }
        }
    ) { innerPadding ->
        //▼メッセージが追加/削除されたとき、最下部へ移動
        LaunchedEffect(messages.size) {
            if (messages.isNotEmpty()) {
                // 1. 最後のアイテムまで一度ジャンプし、Composeにアイテムを描画（レイアウト生成）させる
                listState.scrollToItem(messages.lastIndex)

                // 2. 描画が完了し、画面内に最後のアイテムが実際に表示されるまで待機
                snapshotFlow { listState.layoutInfo }
                    .first { info ->
                        info.visibleItemsInfo.any { it.index == messages.lastIndex }
                    }

                // 3. 画面サイズ基準でどれだけアイテムがはみ出るかの差分を計算
                // 3-1. レイアウト情報取得
                val layoutInfo = listState.layoutInfo
                // 3-2. 最後のアイテムを取得
                val lastItem = layoutInfo.visibleItemsInfo.last()
                // 3-3. アイテムの高さ - リストの表示高さ
                val offset = lastItem.size - layoutInfo.viewportSize.height

                // 4. アイテムの高さが画面に収まらない場合のみ、下端が切れないように再ジャンプで微調整
                if (offset > 0) {
                    listState.scrollToItem(messages.lastIndex, offset)
                }
            }
        }

        //▼IMEに追従してLazyColumnのスクロール位置補正
        class Ref<T>(var value: T)
        var lastViewportHeight by remember { mutableIntStateOf(0) }
        val current = listState.layoutInfo.viewportSize.height
        LaunchedEffect(listState.layoutInfo.viewportSize.height) {
            if (lastViewportHeight != 0) {
                val diff = lastViewportHeight - current
                Log.d("before ",
                    "viewHeight=${current} " + // 今の viewport の高さ（IME 開閉で変化する）
                    "lastViewportHeight=${lastViewportHeight} " + // 前回の viewport の高さ（差分計算の基準）
                    "index=${listState.firstVisibleItemIndex} " + // 画面の一番上に見えてるアイテムの番号
                    "offset=${listState.firstVisibleItemScrollOffset} " + // その index のアイテムのスクロール位置
                    "start=${listState.layoutInfo.viewportStartOffset} " + // viewport の上端（ほぼ 0）
                    "end=${listState.layoutInfo.viewportEndOffset} " + // viewport の下端（＝viewHeight）
                    "diff=${diff} " + // viewport の高さ変化量（IME の開閉量）
                    "last_offset=${listState.layoutInfo.visibleItemsInfo.last().offset} " + // 最後のアイテムの表示開始位置
                    "last_size=${listState.layoutInfo.visibleItemsInfo.last().size} " // 最後のアイテムの高さ
                )
                listState.scrollBy(diff.toFloat())

                Log.d("after ",
                    "viewHeight=${current} " + // 今の viewport の高さ（IME 開閉で変化する）
                    "lastViewportHeight=${lastViewportHeight} " + // 前回の viewport の高さ（差分計算の基準）
                    "index=${listState.firstVisibleItemIndex} " + // 画面の一番上に見えてるアイテムの番号
                    "offset=${listState.firstVisibleItemScrollOffset} " + // その index のアイテムのスクロール位置
                    "start=${listState.layoutInfo.viewportStartOffset} " + // viewport の上端（ほぼ 0）
                    "end=${listState.layoutInfo.viewportEndOffset} " + // viewport の下端（＝viewHeight）
                    "diff=${diff} " + // viewport の高さ変化量（IME の開閉量）
                    "last_offset=${listState.layoutInfo.visibleItemsInfo.last().offset} " + // 最後のアイテムの表示開始位置
                    "last_size=${listState.layoutInfo.visibleItemsInfo.last().size} " // 最後のアイテムの高さ
                )
            }
            lastViewportHeight = current
        }

        LazyColumn(
            modifier = Modifier.Companion
                .fillMaxSize()
                .padding(innerPadding),
            state = listState,
            verticalArrangement = Arrangement.Bottom // 下貼り付き
        ) {
            items(messages) { msg ->
                MessageBubble(text = msg)
            }
        }
    }
}